            "position": {
              "x": 20,
              "y": 270,
              "w": 930,
              "h": 300
            }
          },
          {
            "item": "viz_9",
            "type": "block",
            "position": {
              "x": 970,
              "y": 270,
              "w": 470,
              "h": 300
            }
          },
          {
