              "w": 690,
              "h": 290
            }
          },
          {
            "item": "viz_12",
            "type": "block",
            "position": {
              "x": 20,
              "y": 900,
              "w": 710,
              "h": 320
            }
          },
          {
            "item": "viz_13",
            "type": "block",
            "position": {
              "x": 750,
              "y": 900,
              "w": 690,
              "h": 320
            }
          },
          {
            "item": "viz_14",
            "type": "block",
            "position": {
              "x": 20,
              "y": 1240,
              "w": 1420,
              "h": 340
            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Scenario",
          "layoutId": "layout_1"
        }
      ]
    }
  },
  "expressions": {},
